document.documentElement.classList.toggle('platform-mac', window.minmaxOverlay?.platform === 'darwin');
const initialInventory = JSON.parse(document.querySelector("#profile-data").textContent);
let inventory = Array.isArray(initialInventory) ? { characters: initialInventory, vault: [] } : initialInventory;
let characters = inventory.characters;
let selectedLocation = characters[0]?.id || "vault";
let vaultSearch = "";
let vaultType = "all";
let previousViewKey;
let previousTabsKey;
const itemsById = new Map();
const labels = { barrel: 'Barrel', magazine: 'Magazine', perkOne: 'Perk 1', perkTwo: 'Perk 2' };
const characterList = document.querySelector('#characters'); const details = document.querySelector('#details');
function element(tag, className, text) {
  const node = document.createElement(tag);
  node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function summaryIcon(kind, source) {
  const icon = element('img', kind + '-icon');
  icon.src = source;
  icon.alt = '';
  icon.setAttribute('aria-hidden', 'true');
  return icon;
}

// Bungie manifest element images and Destiny ammo assets; see assets/destiny/README.md.
const elementSymbols = {"Stasis": "data:image/png;base64,", "Solar": "data:image/png;base64,", "Arc": "data:image/png;base64,", "Kinetic": "data:image/png;base64,", "Void": "data:image/png;base64,", "Strand": "data:image/png;base64,"};
const ammoSymbols = {"Primary": "data:image/svg+xml;base64,", "Special": "data:image/svg+xml;base64,", "Heavy": "data:image/svg+xml;base64,"};

function previewFor(item) {
  const preview = element('aside', 'preview');
  preview.setAttribute('role', 'tooltip');
  preview.dataset.tier = item.tierType ?? 5;
  const heading = element('div', 'item-heading');
  heading.append(element('h3', '', item.name));
  const subtitle = element('div', 'item-subtitle');
  subtitle.append(element('span', '', item.category), element('span', '', item.tier));
  heading.append(subtitle);
  const states = element('div', 'item-state-labels');
  if (item.recommendation?.rating) {
    const rating = element('span', 'aegis-rating', item.recommendation.rating);
    rating.dataset.rating = item.recommendation.rating[0];
    rating.title = 'Aegis rating: ' + item.recommendation.rating;
    rating.setAttribute('aria-label', rating.title);
    states.append(rating);
  }
  if (item.gearTier) states.append(element('span', 'gear-tier-label', 'Gear Tier ' + item.gearTier));
  if (item.masterworked) states.append(element('span', 'masterwork-label', '◆ Masterworked'));
  if (item.enhanced) states.append(element('span', 'enhanced-label', '✦ Enhanced'));
  if (item.crafted) states.append(element('span', 'crafted-label', 'Crafted'));
  if (states.childElementCount) heading.append(states);
  preview.append(heading);

  const summary = element('div', 'item-summary');
  const powerLine = element('div', 'item-power-line');
  if (item.power !== null) powerLine.append(element('span', 'item-power', item.power));
  if (item.damage) {
    const damage = element('span', 'damage damage-' + item.damage.toLowerCase());
    if (elementSymbols[item.damage]) damage.append(summaryIcon('damage', elementSymbols[item.damage]));
    damage.append(document.createTextNode(item.damage));
    powerLine.append(damage);
  }
  if (item.ammo) {
    const ammo = element('span', 'ammo ammo-' + item.ammo.toLowerCase());
    if (ammoSymbols[item.ammo]) ammo.append(summaryIcon('ammo', ammoSymbols[item.ammo]));
    ammo.append(document.createTextNode(item.ammo));
    powerLine.append(ammo);
  }
  summary.append(powerLine);
  if (item.tracker) {
    const tracker = element('div', 'item-tracker');
    tracker.append(element('span', '', item.tracker.label), element('span', '', item.tracker.value.toLocaleString()));
    summary.append(tracker);
  }
  preview.append(summary);

  const stats = element('div', 'item-stats');
  for (const stat of item.stats ?? []) {
    const row = element('div', 'item-stat' + (stat.numeric ? ' numeric' : ''));
    row.append(element('span', 'stat-name', stat.name));
    const masterworkBonus = stat.masterworkBonus ?? 0;
    const tierBonus = stat.tierBonus ?? 0;
    const hasBonus = masterworkBonus !== 0 || tierBonus !== 0;
    if (!stat.numeric) {
      const track = element('div', 'stat-track');
      const fill = element('div', 'stat-fill');
      const clamp = (value) => Math.max(0, Math.min(100, value));
      const total = clamp(stat.value);
      const base = Math.min(total, clamp(stat.baseValue ?? stat.value));
      const withMasterwork = Math.min(total, clamp(base + masterworkBonus));
      fill.style.width = (hasBonus ? base : total) + '%';
      track.append(fill);
      if (hasBonus) {
        const masterwork = element('div', 'stat-masterwork-fill');
        masterwork.style.width = Math.max(0, withMasterwork - base) + '%';
        const tier = element('div', 'stat-tier-fill');
        tier.style.width = Math.max(0, total - withMasterwork) + '%';
        track.append(masterwork, tier);
      }
      row.append(track);
    }
    const value = element('span', 'stat-value' + (hasBonus ? ' gold-stat' : ''), stat.value);
    if (hasBonus) {
      const signed = (number) => number >= 0 ? '+' + number : String(number);
      const contributions = [];
      if (masterworkBonus) contributions.push('Masterwork ' + signed(masterworkBonus));
      if (tierBonus) contributions.push('Gear tier ' + signed(tierBonus));
      row.title = stat.name + ': ' + (stat.baseValue ?? stat.value) + ' base · ' + contributions.join(' · ');
      row.setAttribute('aria-label', row.title + ' = ' + stat.value);
    }
    row.append(value);
    stats.append(row);
  }
  if (stats.childElementCount) {
    preview.append(stats);
  }

  const perks = element('div', 'item-perks');
  for (const perk of item.perks ?? []) {
    const row = element('div', 'item-perk' + (perk.intrinsic ? ' intrinsic' : '') + (perk.enhanced ? ' trait-enhanced' : ''));
    if (perk.icon) {
      const icon = element('img', 'perk-icon');
      icon.src = perk.icon;
      icon.alt = '';
      row.append(icon);
    } else row.append(element('span', 'perk-placeholder', '◇'));
    row.append(element('span', '', perk.name));
    if (perk.enhanced) row.append(element('span', 'enhanced-trait-marker', '✦ Enhanced'));
    row.title = (perk.enhanced ? (perk.type || 'Enhanced perk') + '. ' : '') + (perk.description || '');
    perks.append(row);
  }
  if (perks.childElementCount) preview.append(perks);
  if (item.masterwork) {
    const masterwork = element('div', 'item-perk masterwork-stat');
    if (item.masterwork.icon) {
      const icon = element('img', 'perk-icon'); icon.src = item.masterwork.icon; icon.alt = ''; masterwork.append(icon);
    }
    masterwork.append(element('span', '', item.masterwork.name));
    preview.append(masterwork);
  }

  const comparison = element('div', 'item-comparison');
  if (item.score) {
    comparison.append(element('div', 'score', 'Aegis match: ' + item.score.value + ' / ' + item.score.total));
    for (const [field, label] of Object.entries(labels)) {
      const line = element('div', 'slot');
      const values = element('div', 'comparison-values');
      values.append(element('b', item.score.matches[field] ? 'match' : 'miss', item.slots[field] || 'Not installed'));
      const options = item.recommendation?.[field] ?? [];
      values.append(element('small', 'expected-perks', 'Aegis: ' + (options.length ? options.join(' / ') : 'No listed options')));
      line.append(element('span', '', label), values);
      comparison.append(line);
    }
  }
  if (item.excluded) comparison.append(element('p', 'hint', item.excluded));
  if (comparison.childElementCount) preview.append(comparison);
  if (!item.detailsLoaded) preview.append(element("p", "hint preview-loading", "Loading item details…"));
  return preview;
}

function attachPreview(card, item) {
  let preview;
  card.tabIndex = 0;
  let closeTimer;
  let hovered = false;
  const hide = () => preview?.classList.remove('open');
  const position = () => {
    const bounds = card.getBoundingClientRect();
    const width = preview.offsetWidth;
    let left = bounds.right + 12;
    if (left + width > innerWidth - 12) left = bounds.left - width - 12;
    preview.style.left = Math.max(12, Math.min(left, innerWidth - width - 12)) + 'px';
    const topInset = document.documentElement.classList.contains('platform-mac') ? 56 : 12;
    preview.style.top = Math.max(topInset, Math.min(bounds.top, innerHeight - preview.offsetHeight - 12)) + 'px';
  };
  const bindPanel = () => {
    preview.addEventListener('mouseenter', () => clearTimeout(closeTimer));
    preview.addEventListener('mouseleave', scheduleHide);
  };
  const refreshPanel = () => {
    if (!preview) return;
    const replacement = previewFor(item);
    replacement.id = preview.id;
    replacement.classList.toggle('open', preview.classList.contains('open'));
    preview.replaceWith(replacement);
    preview = replacement;
    bindPanel();
    if (preview.classList.contains('open')) position();
  };
  card.addEventListener('item-details-updated', refreshPanel);
  const show = async () => {
    if (draggedItem) return;
    hovered = true;
    clearTimeout(closeTimer);
    if (!preview) {
      preview = previewFor(item);
      preview.id = 'item-preview-' + item.id;
      card.setAttribute('aria-describedby', preview.id);
      card.append(preview);
      bindPanel();
    }
    document.querySelectorAll('.preview.open').forEach((panel) => panel.classList.remove('open'));
    preview.classList.add('open');
    position();
    // Avoid network traffic while the pointer is just passing over gear.
    await new Promise((resolve) => setTimeout(resolve, 100));
    if ((!hovered && document.activeElement !== card) || !preview.classList.contains('open') || !card.isConnected) return;
    if (item.detailsLoaded || !window.minmaxInventory) return;
    if (!item.detailsPromise) item.detailsPromise = window.minmaxInventory.details(item.id).then((details) => {
      Object.assign(item, details, { detailsLoaded: true, detailData: details });
    }).finally(() => { item.detailsPromise = undefined; });
    try {
      await item.detailsPromise;
      if (!card.isConnected) return;
      refreshPanel();
    } catch (error) {
      if (!preview.querySelector('.load-error')) preview.append(element('p', 'hint load-error', 'Details could not load: ' + error.message));
    }
  };
  const scheduleHide = () => { closeTimer = setTimeout(hide, 120); };
  card.addEventListener('mouseenter', show);
  card.addEventListener('mouseleave', () => { hovered = false; scheduleHide(); });
  card.addEventListener('focus', show);
  card.addEventListener('blur', hide);
  card.addEventListener('keydown', (event) => { if (event.key === 'Escape') hide(); });
}

const WEAPON_SLOTS = [
  [1498876634, 'Kinetic'], [2465295065, 'Energy'], [953998645, 'Power'],
];
const ARMOR_SLOTS = [
  [3448274439, 'Helmet'], [3551918588, 'Gauntlets'], [14239492, 'Chest'],
  [20886954, 'Boots'], [1585787867, 'Class item'],
];
function itemCard(item, compact = false) {
  const card = element('article', 'gear-item' + (compact ? ' compact' : '') + (item.equipped ? ' equipped' : '') + (item.masterworked ? ' masterworked' : ''));
  card.dataset.itemId = item.id;
  card.setAttribute('aria-label', item.name + (item.equipped ? ', equipped' : ''));
  if (item.icon) {
    const icon = element('img', 'gear-icon');
    icon.src = item.icon;
    icon.alt = '';
    icon.loading = 'lazy';
    icon.decoding = 'async';
    card.append(icon);
  } else card.append(element('div', 'gear-placeholder', item.name.slice(0, 1)));
  if (item.gearTier) {
    const badge = element('span', 'gear-tier-badge', 'T' + item.gearTier);
    badge.title = 'Destiny 2 Gear Tier ' + item.gearTier; card.append(badge);
  }
  if (item.masterworked) {
    const badge = element('span', 'masterwork-badge', '◆');
    badge.title = 'Masterworked'; badge.setAttribute('aria-label', 'Masterworked'); card.append(badge);
  }
  const copy = element('div', 'gear-copy');
  copy.append(element('strong', '', item.name), element('small', '', item.power === null ? item.category : 'Power ' + item.power));
  card.append(copy);
  card.draggable = Boolean(item.transferable && !item.equipped);
  card.title = item.equipped ? 'Unequip in Destiny 2 to transfer' : card.draggable ? 'Drag onto a character or the Vault to transfer' : 'This item cannot be transferred';
  card.addEventListener('dragstart', (event) => {
    if (moving || !card.draggable) { event.preventDefault(); return; }
    draggedItem = item;
    event.dataTransfer.effectAllowed = 'move';
    event.dataTransfer.setData('text/plain', item.id);
    document.querySelectorAll('.preview.open').forEach((panel) => panel.classList.remove('open'));
    card.classList.add('dragging');
    document.body.classList.add('transferring-drag');
    for (const target of characterList.children) target.classList.toggle('drop-available', target.dataset.location !== item.source);
  });
  card.addEventListener('dragend', clearDrag);
  attachPreview(card, item);
  return card;
}

function slotColumn(character, slots, className) {
  const column = element('div', 'slot-column ' + className);
  for (const [bucket, label] of slots) {
    const group = element('section', 'equipment-slot');
    group.dataset.slot = label;
    group.append(element('h3', 'slot-label', label));
    const items = character.gear.filter((item) => item.bucket === bucket);
    const equipped = items.find((item) => item.equipped);
    group.append(equipped ? itemCard(equipped) : element('div', 'empty-slot', 'No equipped ' + label.toLowerCase()));
    const reserves = element('div', 'reserve-items');
    for (const item of items.filter((item) => !item.equipped)) reserves.append(itemCard(item, true));
    if (reserves.childElementCount) group.append(reserves);
    column.append(group);
  }
  return column;
}

function selectCharacter(character) {
  const layout = element('div', 'guardian-layout');
  const guardian = element('section', 'guardian-summary');
  if (character.emblem) guardian.style.backgroundImage = 'linear-gradient(#10131a88, #10131af5), url("' + character.emblem + '")';
  guardian.append(element('div', 'guardian-label', 'GUARDIAN'), element('h2', '', character.className),
    element('div', 'guardian-power-label', 'POWER'), element('div', 'guardian-power', character.light),
    element('div', 'guardian-sigil', character.className.slice(0, 1)),
    element('p', 'hint', 'Hover to inspect · Drag to transfer'));
  layout.append(slotColumn(character, WEAPON_SLOTS, 'weapon-column'), guardian, slotColumn(character, ARMOR_SLOTS, 'armor-column'));
  details.append(layout);
}

function showVault() {
  const toolbar = element('div', 'vault-toolbar');
  toolbar.append(element('h2', '', inventory.vaultLoading ? 'Vault · Loading…' : inventory.vaultError ? 'Vault · Unavailable' : 'Vault · ' + inventory.vault.length + ' items'));
  const search = element('input', 'vault-search');
  search.type = 'search'; search.placeholder = 'Search vault'; search.value = vaultSearch;
  search.setAttribute('aria-label', 'Search vault');
  const filter = element('select', 'vault-filter');
  filter.setAttribute('aria-label', 'Vault item type');
  for (const [value, label] of [['all', 'All gear'], ['3', 'Weapons'], ['2', 'Armor']]) {
    const option = element('option', '', label); option.value = value; filter.append(option);
  }
  filter.value = vaultType;
  toolbar.append(search, filter);
  const grid = element('div', 'gear vault-grid');
  const more = element('button', 'load-more', 'Load more items');
  more.type = 'button';
  let visibleCount = 60;
  let matches = [];
  const appendPage = (reset = false) => {
    if (reset) grid.replaceChildren();
    const start = reset ? 0 : grid.querySelectorAll('.gear-item').length;
    const fragment = document.createDocumentFragment();
    for (const item of matches.slice(start, visibleCount)) fragment.append(itemCard(item));
    grid.append(fragment);
    more.hidden = visibleCount >= matches.length;
    more.textContent = 'Load more · ' + Math.max(0, matches.length - visibleCount) + ' remaining';
    if (!matches.length) grid.append(element('p', 'empty', inventory.vaultLoading ? 'Loading vault in the background…' : inventory.vaultError || 'No matching items in the vault.'));
  };
  const update = () => {
    vaultSearch = search.value; vaultType = filter.value; visibleCount = 60;
    matches = inventory.vault.filter((item) => item.name.toLowerCase().includes(vaultSearch.toLowerCase()) && (vaultType === 'all' || item.type === Number(vaultType)));
    appendPage(true);
  };
  more.addEventListener('click', () => { visibleCount += 60; appendPage(); });
  search.addEventListener('input', update); filter.addEventListener('change', update);
  details.append(toolbar, grid, more); update();
}

function renderInventory(next = inventory) {
  const retained = new Set();
  const reconcile = (item) => {
    const previous = itemsById.get(item.id);
    const current = previous && previous.detailVersion === item.detailVersion
      ? Object.assign(previous, item, previous.detailData ?? {}) : item;
    itemsById.set(item.id, current); retained.add(item.id);
    return current;
  };
  next.characters = next.characters.map((character) => ({ ...character, gear: character.gear.map(reconcile) }));
  next.vault = next.vault.map(reconcile);
  for (const id of itemsById.keys()) if (!retained.has(id)) itemsById.delete(id);
  inventory = next; characters = next.characters;
  if (next.refreshedAt) document.querySelector("#last-refreshed").textContent = "Last refreshed: " + new Date(next.refreshedAt).toLocaleTimeString();
  if (selectedLocation !== 'vault' && !characters.some((character) => character.id === selectedLocation)) selectedLocation = characters[0]?.id || 'vault';
  const current = characters.find((character) => character.id === selectedLocation);
  const baseItem = ({ id, name, icon, power, bucket, equipped, transferable, detailVersion, gearTier, masterworked, enhanced }) => [id, name, icon, power, bucket, equipped, transferable, detailVersion, gearTier, masterworked, enhanced];
  const viewKey = JSON.stringify([selectedLocation, selectedLocation === 'vault'
    ? [inventory.vaultLoading, inventory.vaultError, inventory.vault.map(baseItem)]
    : [current?.className, current?.light, current?.emblem, current?.gear.map(baseItem)]]);
  const tabsKey = JSON.stringify([selectedLocation, inventory.vaultLoading, inventory.vault.length, characters.map(({ id, className, light }) => [id, className, light])]);
  if (tabsKey !== previousTabsKey) {
    characterList.replaceChildren();
    for (const location of [...characters, { id: 'vault', className: 'Vault' }]) {
      const button = element('button', 'character' + (location.id === selectedLocation ? ' active' : ''));
      button.type = 'button';
      button.dataset.location = location.id;
      attachDropTarget(button, location.id);
      button.setAttribute('aria-pressed', String(location.id === selectedLocation));
      button.append(element('h2', '', location.className));
      button.append(element('p', '', location.id === 'vault' ? (inventory.vaultLoading ? 'Loading…' : inventory.vault.length + ' items') : 'Power ' + location.light));
      button.addEventListener('click', () => { selectedLocation = location.id; renderInventory(); });
      characterList.append(button);
    }
    previousTabsKey = tabsKey;
  }
  if (viewKey === previousViewKey) return;
  previousViewKey = viewKey;
  details.replaceChildren();
  if (selectedLocation === 'vault') showVault();
  else selectCharacter(characters.find((character) => character.id === selectedLocation));
}

let draggedItem;
let moving = false;
function clearDrag() {
  draggedItem = undefined;
  document.body.classList.remove('transferring-drag');
  document.querySelectorAll('.dragging, .drop-available, .drop-hover').forEach((node) => node.classList.remove('dragging', 'drop-available', 'drop-hover'));
}
function attachDropTarget(target, destination) {
  const allowed = () => !moving && draggedItem?.transferable && !draggedItem.equipped && draggedItem.source !== destination;
  target.addEventListener('dragover', (event) => {
    if (!allowed()) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
    target.classList.add('drop-hover');
  });
  target.addEventListener('dragleave', (event) => {
    if (!target.contains(event.relatedTarget)) target.classList.remove('drop-hover');
  });
  target.addEventListener('drop', async (event) => {
    event.preventDefault();
    if (!allowed()) { clearDrag(); return; }
    const item = draggedItem;
    clearDrag();
    moving = true;
    const message = document.querySelector('#inventory-message');
    message.textContent = 'Transferring ' + item.name + '…';
    document.body.classList.add('transfer-busy');
    try {
      const result = await window.minmaxInventory.transfer({ id: item.id, source: item.source, destination });
      message.textContent = result.message;
    } catch (error) { message.textContent = error.message; }
    finally { moving = false; document.body.classList.remove('transfer-busy'); }
  });
}
renderInventory();
window.minmaxInventory?.onUpdate(renderInventory);
window.minmaxInventory?.onDetails?.(({ id, details: data }) => {
  const item = itemsById.get(id);
  if (!item) return;
  Object.assign(item, data, { detailsLoaded: true, detailData: data });
  for (const card of document.querySelectorAll('.gear-item')) {
    if (card.dataset.itemId === id) card.dispatchEvent(new Event('item-details-updated'));
  }
});

window.addEventListener('resize', () => document.querySelectorAll('.preview.open').forEach((panel) => panel.classList.remove('open')));
window.addEventListener('scroll', (event) => {
  if (event.target instanceof Element && event.target.closest('.preview')) return;
  document.querySelectorAll('.preview.open').forEach((panel) => panel.classList.remove('open'));
}, true);

const clearOverlay = document.querySelector('#clear-overlay');
async function updateOverlayStatus(action) {
  clearOverlay.disabled = true;
  try {
    const state = await action();
    clearOverlay.title = state.message;
  } catch (error) {
    clearOverlay.title = 'Overlay unavailable: ' + error.message;
  } finally {
    clearOverlay.disabled = false;
  }
}
clearOverlay.addEventListener('click', () => updateOverlayStatus(() => window.minmaxOverlay.clear()));
document.querySelector('#close-app').addEventListener('click', () => window.minmaxOverlay.close());
updateOverlayStatus(() => window.minmaxOverlay.status());

window.minmaxOverlay.onVisibility((cleared) => {
  document.documentElement.classList.toggle('overlay-clear', cleared);
});
